    "dur-slow": string;
    ease: string;
    "dur-surface": string;
    "dur-flow": string;
    "dur-progress": string;
    "ease-quiet": string;
    // v0.2.0 workflow + reading
    "stage-active": string;
    "stage-done": string;
    "stage-running": string;
    "stage-stale": string;
    "facts-paper": string;
    "facts-ink": string;
